import random
from math import gcd

def extended_euclidean(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, x, y = extended_euclidean(b, a % b)
        return (g, y, x - (a // b) * y)

def generate(seed):
    rng = random.Random(seed)

    while True:
        a = rng.randint(1, 100)  # Ensure a is positive
        b = rng.randint(1, 100)  # Ensure b is positive
        m = rng.randint(2, 100)  # Ensure m is greater than 1
        c = rng.randint(0, m - 1)  # Ensure c is less than m

        # Ensure that the linear Diophantine equation has a solution
        if gcd(a, m) != 1:
            continue

        # Solve for x using the Extended Euclidean Algorithm
        g, x, y = extended_euclidean(a, m)
        if c % g != 0:
            continue

        # Ensure x is positive and minimal
        x = (x * (c // g)) % m
        if x == 0:
            x += m

        # Brute-force to ensure correctness
        answer_brute = None
        for x_brute in range(m):
            if (a * x_brute) % m == c:
                answer_brute = x_brute
                break

        # Cross-check both paths
        assert answer_brute == x, (
            f"path mismatch a={a} m={m} c={c}: "
            f"insight={x} brute={answer_brute}"
        )

        problem = (
            f"Find the smallest positive integer x such that "
            f"{a}x ≡ {c} (mod {m})."
        )
        return problem, str(x)

