import random
import sympy

def generate(seed):
    rng = random.Random(seed)
    while True:
        a = rng.randint(3, 99)  # Side length is a two-digit number
        b = rng.randint(3, 99)  # Side length is a two-digit number
        if a == b:
            continue  # Ensure sides are distinct
        if sympy.isprime(a) and sympy.isprime(b):
            break

    problem = (
        f"A parallelogram has sides of lengths {a} and {b} units, which are distinct two-digit prime numbers. What is the perimeter of the parallelogram?"
    )
    answer = 2 * (a + b)
    return problem, str(sympy.Integer(answer))

